        U=('security adviser', 'Professionals who study the threat and sell what they know: the risk report, the safe route.'),
        B=('sellsword or firm owner', 'Skill sold openly at its worth, to whoever pays, owing no lord.'),
        R=('caravan guard on the far road', 'Adventurers who take the far road for the pay, the danger and the story.'),
